const OVERRIDES = {
  '174kgJ_nJLraVG4bBTD_DPpBR9tLvG62w': 'Creative & Social Operating Model'
};
const EXCLUDE_RE = /notes by gemini|weekly meeting|notes for call|meeting notes|call notes|recap notes|^think technologies\s*\|/i;

function cleanName(raw, clientName) {
  let s = String(raw || '').replace(/\.[a-zA-Z0-9]{2,5}$/, '');
  s = s.replace(/_/g, ' ');
  if (clientName) {
    const esc = clientName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    s = s.replace(new RegExp(esc, 'ig'), '');
  }
  s = s.replace(/\bthink technologies\b/ig, '');
  s = s.replace(/\b(final|draft|copy of|v\d+)\b/ig, '');
  s = s.replace(/\s{2,}/g, ' ').trim();
  s = s.replace(/^[-|:\s]+|[-|:\s]+$/g, '').trim();
  if (!s) s = String(raw || '').replace(/\.[a-zA-Z0-9]{2,5}$/, '');
  return s;
}

const clientName = ($('Portal Drive Files Webhook').first().json.body || {}).clientName || '';
const items = $input.all().map(i => i.json).filter(f => !EXCLUDE_RE.test(f.name || ''));
const files = items.map(f => ({
  ...f,
  displayName: OVERRIDES[f.id] || cleanName(f.name, clientName)
}));
return [{ json: { files } }];
